'use client';

import Image from 'next/image';
import {
  ArrowLeft,
  BatteryCharging,
  ChevronLeft,
  ChevronRight,
  Droplets,
  Gauge,
} from 'lucide-react';
import { useEffect, useState } from 'react';

const slides = [
  {
    image: '/images/hero-tire.jpeg',
    alt: 'إطار Mero على سيارة رياضية',
    eyebrow: 'هندسة الإطارات الفائقة للظروف الصحراوية',
    title: 'إطارات عالية الجودة',
    accent: 'لرحلة أكثر أماناً',
    description: 'ثبات مطلق وتحكم استثنائي مع كل ما تحتاجه سيارتك في مكان واحد.',
    cta: 'تصفح الإطارات المعتمدة',
    icon: Gauge,
    meta: ['السعودية', 'الإمارات'],
  },
  {
    image: '/images/hero-battery.jpeg',
    alt: 'بطارية Mero مع سيارة على الطريق',
    eyebrow: 'طاقة تشغيلية مستدامة • High Cranking Power',
    title: 'بطاريات فائقة الطاقة',
    accent: 'لتحمل أقصى الظروف',
    description: 'قوة تشغيلية فورية مصممة للتعامل مع درجات الحرارة العالية دون انقطاع.',
    cta: 'استكشف أنواع البطاريات',
    icon: BatteryCharging,
    meta: ['ضمان شامل', 'جاهزية التبديل السريع'],
  },
  {
    image: '/images/hero-oil.jpeg',
    alt: 'زيوت وفلاتر Mero',
    eyebrow: 'زيوت تخليقية بالكامل • 5W-30 / 10W-40',
    title: 'زيوت محركات متطورة',
    accent: 'وقطع غيار بأعلى كفاءة',
    description: 'حماية متقدمة للمحرك مع زيوت وفلاتر مختارة للعناية المستمرة.',
    cta: 'عرض الزيوت والفلاتر',
    icon: Droplets,
    meta: ['حماية محرك مضاعفة', 'تشكيلة متكاملة'],
  },
];

export default function HeroCarousel() {
  const [active, setActive] = useState(0);
  const current = slides[active];
  useEffect(() => {
    const timer = window.setInterval(() => setActive((value) => (value + 1) % slides.length), 5000);
    return () => window.clearInterval(timer);
  }, []);
  const previous = () => setActive((value) => (value - 1 + slides.length) % slides.length);
  const next = () => setActive((value) => (value + 1) % slides.length);
  return (
    <section
      id="top"
      aria-roledescription="carousel"
      aria-label="منتجات Mero"
      className="relative h-[650px] overflow-hidden pt-[72px] lg:h-[750px]"
    >
      {slides.map((slide, index) => (
        <div
          key={slide.image}
          aria-hidden={index !== active}
          className={`absolute inset-0 transition-opacity duration-1000 ${index === active ? 'z-10 opacity-100' : 'pointer-events-none z-0 opacity-0'}`}
        >
          <Image
            src={slide.image}
            alt={slide.alt}
            fill
            priority={index === 0}
            className="object-cover object-center"
          />
          <div className="absolute inset-0 bg-gradient-to-l from-void via-void/85 via-45% to-transparent" />
          <div className="absolute inset-0 bg-gradient-to-t from-void via-void/20 to-void/20" />
        </div>
      ))}
      <div className="container relative z-20 flex h-full items-center">
        <div className="max-w-xl rounded-xl bg-void/30 p-5 text-right backdrop-blur-[1px] sm:p-7 lg:bg-transparent lg:p-0">
          <div className="label mb-4 inline-flex items-center gap-2 rounded-full border border-gold/40 bg-gold/10 px-3 py-2 text-gold">
            <current.icon size={14} />
            {current.eyebrow}
          </div>
          <h1 className="font-arabic text-4xl font-bold leading-[1.25] text-white sm:text-5xl lg:text-[50px]">
            {current.title}
            <br />
            <span className="text-gold">{current.accent}</span>
          </h1>
          <p className="mt-4 max-w-lg text-base leading-8 text-[#d0c5af]">{current.description}</p>
          <div className="mt-7 flex flex-wrap gap-3">
            <a className="btn btn-primary" href="#products">
              {current.cta}
              <ArrowLeft size={16} className="mr-2" />
            </a>
            <a className="btn btn-secondary" href="#contact">
              تواصل معنا
            </a>
          </div>
          <div className="mt-7 flex items-center gap-4 text-xs text-white/80">
            {current.meta.map((item, index) => (
              <span key={item}>
                {index > 0 && <i className="ml-4 inline-block h-4 w-px bg-white/20" />}
                {item}
              </span>
            ))}
          </div>
        </div>
      </div>
      <div className="absolute bottom-5 left-0 right-0 z-30">
        <div className="container flex items-end justify-between gap-4">
          <div className="flex items-center gap-2 rounded-xl border border-white/10 bg-void/80 p-2 backdrop-blur-xl">
            {slides.map((slide, index) => (
              <button
                key={slide.title}
                aria-label={`عرض ${slide.title}`}
                aria-current={index === active}
                onClick={() => setActive(index)}
                className={`hidden min-h-12 items-center gap-2 rounded-lg px-3 text-right text-[10px] sm:flex ${index === active ? 'border border-gold/60 bg-raised text-white' : 'text-muted'}`}
              >
                <span
                  className={`grid h-7 w-7 place-items-center rounded-full border ${index === active ? 'border-gold text-gold' : 'border-white/15'}`}
                >
                  0{index + 1}
                </span>
                <span>
                  {index === 0
                    ? 'الإطارات الفاخرة'
                    : index === 1
                      ? 'البطاريات عالية الطاقة'
                      : 'الزيوت والقطع'}
                </span>
              </button>
            ))}
          </div>
          <div className="flex items-center gap-3 rounded-full border border-white/10 bg-void/80 px-3 py-2 text-white backdrop-blur-xl">
            <button aria-label="الشريحة السابقة" onClick={previous}>
              <ChevronRight size={16} />
            </button>
            <span className="text-xs font-bold text-gold" dir="ltr">
              0{active + 1} / 03
            </span>
            <button aria-label="الشريحة التالية" onClick={next}>
              <ChevronLeft size={16} />
            </button>
          </div>
        </div>
      </div>
    </section>
  );
}
